<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/userService.php';require_once __DIR__.'/../includes/auth.php';startSecureSession();if(!empty($_SESSION['user_id'])){header('Location: profile.php',true,303);exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);$u=authenticateUser(openDatabase(),(string)($_POST['email']??''),(string)($_POST['password']??''));if(!$u){$error='Invalid email or password.';}else{session_regenerate_id(true);$_SESSION['user_id']=(int)$u['user_id'];$_SESSION['display_name']=$u['full_name'];$_SESSION['role']=$u['role'];$_SESSION['last_activity']=time();csrfToken();header('Location: profile.php',true,303);exit;}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?>
